// build checks the graph's inputs, then builds a root.
func (g *Graph) build(root string, force func()) error {
	var missing []string
	if g.Ctx == nil {
		missing = append(missing, "Ctx")
	}
	if g.Cfg == nil {
		missing = append(missing, "Cfg")
	}
	if g.Log == nil {
		missing = append(missing, "Log")
	}
	if len(missing) > 0 {
		return fmt.Errorf("build %s: set app.Graph's %s before building a root", root, strings.Join(missing, ", "))
	}
	return g.b.Build(root, force)
}

// Built names every node Build constructed, each after its dependencies.
func (g *Graph) Built() []string { return g.b.Built() }

// BuildGateway constructs the gateway root — every node its fields
// reach, once, dependencies first — then seals the graph. Start order as
// compose.go wires it today (stop is the reverse):
//
//	pprof → db_repo → nats_conn → user_update_hub → daemon_state_publisher → tool_result_publisher → tools_daemon → flow_health → tools_daemon_sweeper → state_derivation → jet_stream → tool_bridge → daemon_event_publisher → connection_listeners → activity_subscriber → tls_files → token_authority → daemon_auth → daemon_chain → daemon_routes → daemon_listener → daemon_connector → managed_reconciler
func (g *Graph) BuildGateway() (*Gateway, error) {
	if g.DatabaseConfig == nil {
		return nil, fmt.Errorf("build gateway: set app.Graph's DatabaseConfig before building the root: its closure reads it")
	}
	if g.GatewayConfig == nil {
		return nil, fmt.Errorf("build gateway: set app.Graph's GatewayConfig before building the root: its closure reads it")
	}
	if g.ServerProcessConfig == nil {
		return nil, fmt.Errorf("build gateway: set app.Graph's ServerProcessConfig before building the root: its closure reads it")
	}
	r := &Gateway{}
	err := g.build("gateway", func() {
		// Last field first, so the first field starts last and stops first.
		r.Pprof = g.Pprof()
		r.FlowHealth = g.FlowHealth()
		r.ToolsDaemon = g.ToolsDaemonSweeper()
		r.Derivation = g.StateDerivation()
		r.Bridge = g.ToolBridge()
		r.Listeners = g.ConnectionListeners()
		r.Activity = g.ActivitySubscriber()
		r.Daemon = g.DaemonListener()
		r.Reconciler = g.ManagedReconciler()
	})
	if err != nil {
		return nil, err
	}
	return r, nil
}

// RunGateway builds the gateway root and supervises what it built until
// ctx ends or a node fails: every node that reports Ready joins g.Probes'
// /readyz, and g.Probes' Drainer is the stop policy's readiness gate and
// budget unless policy names one.
// No node the root reaches serves g.Probes, so a probe listener on the server
// address does: started before every node, stopped after them.
func (g *Graph) RunGateway(ctx context.Context, policy lifecyclekit.Policy) error {
	if _, err := g.BuildGateway(); err != nil {
		return err
	}
	probes, err := g.probeListener()
	if err != nil {
		return fmt.Errorf("build gateway: %w", err)
	}
	return g.b.Supervise(ctx, policy, g.Probes, probes...)
}

// PlanGateway is the gateway root's plan, read off compose.go when this
// file was generated: every node BuildGateway constructs, in order, and
// the lifecycle methods each one's type has. RunGateway starts the
// supervised ones in this order and stops them in reverse, so a test pins the
// stop order (Plan.Stop) without constructing anything.
// The probe listener comes first: it starts before every node and stops after
// them.
func PlanGateway() graphkit.Plan {
	return graphkit.Plan{
		{Name: "probe_listener", Run: true, Drain: true, Close: true, Ready: true},
		{Name: "pprof", Run: true, Close: true},
		{Name: "db_repo", Close: true, Ready: true},
		{Name: "nats_conn", Close: true, Ready: true},
		{Name: "user_update_hub", Close: true},
		{Name: "daemon_state_publisher"},
		{Name: "tool_result_publisher"},
		{Name: "tools_daemon"},
		{Name: "flow_health"},
		{Name: "tools_daemon_sweeper", Run: true, Close: true},
		{Name: "state_derivation", Run: true},
		{Name: "jet_stream"},
		{Name: "tool_bridge", Close: true},
		{Name: "daemon_event_publisher"},
		{Name: "connection_listeners"},
		{Name: "activity_subscriber", Close: true},
		{Name: "tls_files"},
		{Name: "token_authority"},
		{Name: "daemon_auth"},
		{Name: "daemon_chain"},
		{Name: "daemon_routes"},
		{Name: "daemon_listener", Run: true, Drain: true, Close: true, Ready: true},
		{Name: "daemon_connector"},
		{Name: "managed_reconciler", Run: true, Close: true},
	}
}

// BuildWorker constructs the worker root — every node its fields
// reach, once, dependencies first — then seals the graph. Start order as
// compose.go wires it today (stop is the reverse):
//
//	integration_settings → process_settings → db_repo → process_runtime → debug_server → nats_conn → user_update_hub → chat_update_hub → repo_update_feed → payload_store → temporal_client → streaming_hub → account_recorder → write_ledger → write_ledger_prune → account_usage_poller → workflow_event_relay → pause_service → run_lifecycle → run_launcher → worker_daemon_router → worker_chat → worker_run → agent_runs → vault → trigger_pollers → worker_trigger → worker_integration_credentials → worker_catalog_search → worker_tools_factory → remote_executor → stored_config_provider → temporal_worker
